class Solution { fun constructProductMatrix(grid:Array<IntArray>):Array<IntArray>{val mod=12345;val rows=grid.size;val columns=grid[0].size;val answer=Array(rows){IntArray(columns)};var prefix=1L;for(row in 0 until rows)for(column in 0 until columns){answer[row][column]=prefix.toInt();prefix=prefix*(grid[row][column]%mod).toLong()%mod};var suffix=1L;for(row in rows-1 downTo 0)for(column in columns-1 downTo 0){answer[row][column]=(answer[row][column].toLong()*suffix%mod).toInt();suffix=suffix*(grid[row][column]%mod).toLong()%mod};return answer} }
